FROM "hl_poslanec" LEFT JOIN "poslanec" ON "hl_poslanec"."id_poslanec" = "poslanec"."id_poslanec" JOIN "osoby" ON "poslanec"."id_osoba" = "osoby"."id_osoba" WHERE "poslanec"."id_obdobi" = 166 AND "hl_poslanec"."id_poslanec" <= 1480 AND "hl_poslanec"."id_poslanec" >= 1322 LIMIT 29;

SELECT "organy"."id_organ", "organy"."id_typ_organu", "schuze_stav"."text_st", "organy"."id_organ"
FROM "schuze_stav" JOIN "schuze" ON "schuze_stav"."id_schuze" = "schuze"."id_schuze" LEFT JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" LIMIT 33;

SELECT "hl_zposlanec"."id_osoba", "hl_zposlanec"."mode", "hl_check"."id_h2"
FROM "hl_zposlanec" LEFT JOIN "hl_hlasovani" ON "hl_zposlanec"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" LEFT JOIN "hl_check" ON "hl_hlasovani"."id_hlasovani" = "hl_check"."id_hlasovani" WHERE "hl_hlasovani"."cas" = 'default' AND "hl_check"."id_h3" = '61406' LIMIT 61;

SELECT "schuze"."id_schuze", "schuze"."od_schuze"
FROM "schuze" WHERE "schuze"."id_organ" != 167 AND "schuze"."aktualizace" != '2000-06-26 12:00' LIMIT 43;

SELECT "hl_check"."id_h3", "hl_check"."id_h3"
FROM "hl_check" JOIN "hl_hlasovani" ON "hl_check"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" LEFT JOIN "zmatecne" ON "hl_hlasovani"."id_hlasovani" = "zmatecne"."id_hlasovani" WHERE "hl_check"."turn" != 61 LIMIT 16;

SELECT "hl_check"."id_h2", "hl_check"."id_h2", "zmatecne"."id_hlasovani", "hl_check"."turn", "zmatecne"."id_hlasovani"
FROM "zmatecne" LEFT JOIN "hl_hlasovani" ON "zmatecne"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" JOIN "hl_check" ON "hl_hlasovani"."id_hlasovani" = "hl_check"."id_hlasovani" LIMIT 22;

SELECT "omluvy"."od", "omluvy"."id_organ", "omluvy"."den"
FROM "poslanec" JOIN "omluvy" ON "poslanec"."id_poslanec" = "omluvy"."id_poslanec" JOIN "pkgps" ON "poslanec"."id_poslanec" = "pkgps"."id_poslanec" WHERE "pkgps"."delka" >= 17.42102612759522 LIMIT 89;

SELECT "schuze_stav"."typ", "schuze_stav"."tm_line", "schuze_stav"."typ", "schuze"."id_organ", "schuze"."schuze"
FROM "schuze_stav" LEFT JOIN "schuze" ON "schuze_stav"."id_schuze" = "schuze"."id_schuze" WHERE "schuze"."id_schuze" <= 372 AND "schuze_stav"."stav" <= 3 LIMIT 59;

SELECT "hl_check"."id_h3", "hl_hlasovani"."zdrzel", "hl_hlasovani"."datum", "hl_hlasovani"."cas"
FROM "hl_check" LEFT JOIN "hl_hlasovani" ON "hl_check"."id_hlasovani" = "hl_hlasovani"."id_hlasovani" WHERE "hl_check"."id_h3" = '58612' AND "hl_check"."id_h2" != '61658' AND "hl_hlasovani"."datum" = '2023-05-16' LIMIT 12;

SELECT "omluvy"."id_poslanec", "omluvy"."id_poslanec", "poslanec"."id_poslanec", "hl_poslanec"."vysledek"
FROM "hl_poslanec" LEFT JOIN "poslanec" ON "hl_poslanec"."id_poslanec" = "poslanec"."id_poslanec" JOIN "omluvy" ON "poslanec"."id_poslanec" = "omluvy"."id_poslanec" WHERE "poslanec"."ulice" = '\' LIMIT 34;

SELECT "funkce"."id_funkce", "funkce"."nazev_funkce_cz"
FROM "funkce" WHERE "funkce"."nazev_funkce_cz" != 'Místopředseda výboru' LIMIT 92;

SELECT "zarazeni"."id_osoba", "zarazeni"."do_f"
FROM "hl_zposlanec" JOIN "osoby" ON "hl_zposlanec"."id_osoba" = "osoby"."id_osoba" JOIN "zarazeni" ON "osoby"."id_osoba" = "zarazeni"."id_osoba" WHERE "osoby"."za" IS NOT NULL LIMIT 17;

SELECT "organy"."do_organ", "organy"."organ_id_organ", "organy"."organ_id_organ", "schuze"."schuze"
FROM "bod_schuze" JOIN "schuze" ON "bod_schuze"."id_schuze" = "schuze"."id_schuze" LEFT JOIN "organy" ON "schuze"."id_organ" = "organy"."id_organ" WHERE "bod_schuze"."id_schuze" <= 140 LIMIT 48;

SELECT "bod_schuze"."id_bod_stav", "bod_schuze"."pozvanka", "bod_schuze"."rj"
FROM "bod_schuze" WHERE "bod_schuze"."id_typ" = '3' AND "bod_schuze"."zkratka" IS NOT NULL AND "bod_schuze"."id_sd" IS NOT NULL LIMIT 25;

SELECT "organy"."cl_organ_base", "organy"."od_organ", "organy"."zkratka"
FROM "organy" LIMIT 94;

SELECT "hl_check"."id_h3", "hl_hlasovani"."zdrzel"
FROM "hl_hlasovani" LEFT JOIN "hl_check" ON "hl_hlasovani"."id_hlasovani" = "hl_check"."id_hlasovani" LEFT JOIN "hl_vazby" ON "hl_hlasovani"."id_hlasovani" = "hl_vazby"."id_hlasovani" WHERE "hl_check"."turn" >= 129 AND "hl_hlasovani"."cas" = 'default' LIMIT 88;

